## Task 18: Auth Service and Guards

**Files:**
- Create: `ui/src/app/auth/auth.service.ts`
- Create: `ui/src/app/auth/auth.guard.ts`
- Create: `ui/src/app/auth/auth.interceptor.ts`
- Create: `ui/src/app/auth/login/login.component.ts`
- Create: `ui/src/app/auth/login/login.component.html`
- Create: `ui/src/app/auth/login/login.component.scss`
- Create: `ui/src/app/auth/callback/auth-callback.component.ts`
- Modify: `ui/src/app/app.config.ts`
- Modify: `ui/src/app/app.routes.ts`

- [ ] **Step 1: Create User model**

Create `ui/src/app/models/user.model.ts`:

```typescript
export interface User {
  id: number;
  displayName: string;
  email: string;
  profileImage: string;
  aboutMe: string;
  reputation: number;
  badgeBronze: number;
  badgeSilver: number;
  badgeGold: number;
  isEmployee: boolean;
  createdAt: string;
  lastAccessAt: string;
}
```

- [ ] **Step 2: Create AuthService**

Create `ui/src/app/auth/auth.service.ts`:

```typescript
import { Injectable, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { Observable, tap, catchError, of } from 'rxjs';
import { User } from '../models/user.model';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly apiBase = '/api/v1';
  readonly currentUser = signal<User | null>(null);
  readonly isLoading = signal(true);

  constructor(private http: HttpClient, private router: Router) {}

  loadCurrentUser(): Observable<User | null> {
    return this.http.get<User>(`${this.apiBase}/auth/me`, { withCredentials: true }).pipe(
      tap(user => {
        this.currentUser.set(user);
        this.isLoading.set(false);
      }),
      catchError(() => {
        this.currentUser.set(null);
        this.isLoading.set(false);
        return of(null);
      })
    );
  }

  login(): void {
    window.location.href = `${this.apiBase}/auth/login`;
  }

  devLogin(): Observable<User> {
    return this.http.post<User>(`${this.apiBase}/auth/dev-login`, {}, { withCredentials: true }).pipe(
      tap(user => this.currentUser.set(user))
    );
  }

  logout(): Observable<void> {
    return this.http.post<void>(`${this.apiBase}/auth/logout`, {}, { withCredentials: true }).pipe(
      tap(() => {
        this.currentUser.set(null);
        this.router.navigate(['/login']);
      })
    );
  }

  isAuthenticated(): boolean {
    return this.currentUser() !== null;
  }
}
```

- [ ] **Step 3: Create AuthGuard**

Create `ui/src/app/auth/auth.guard.ts`:

```typescript
import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from './auth.service';
import { map, switchMap, of } from 'rxjs';

export const authGuard: CanActivateFn = () => {
  const auth = inject(AuthService);
  const router = inject(Router);

  if (auth.currentUser() !== null) {
    return of(true);
  }

  return auth.loadCurrentUser().pipe(
    map(user => {
      if (user) return true;
      return router.createUrlTree(['/login']);
    })
  );
};
```

- [ ] **Step 4: Create auth interceptor**

Create `ui/src/app/auth/auth.interceptor.ts`:

```typescript
import { HttpInterceptorFn } from '@angular/common/http';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  return next(req.clone({ withCredentials: true }));
};
```

- [ ] **Step 5: Create LoginComponent**

Create `ui/src/app/auth/login/login.component.ts`:

```typescript
import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { AuthService } from '../auth.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './login.component.html',
  styleUrl: './login.component.scss'
})
export class LoginComponent implements OnInit {
  protected auth = inject(AuthService);
  private router = inject(Router);
  protected isDevMode = false;

  ngOnInit(): void {
    // Check if already logged in
    this.auth.loadCurrentUser().subscribe(user => {
      if (user) this.router.navigate(['/questions']);
    });
    // Dev mode detection: backend sets a flag in the HTML or we check a known endpoint
    fetch('/api/v1/auth/mode').then(r => r.json()).then((data: { mode: string }) => {
      this.isDevMode = data.mode === 'static';
    }).catch(() => {});
  }

  protected onLogin(): void {
    this.auth.login();
  }

  protected onDevLogin(): void {
    this.auth.devLogin().subscribe(() => {
      this.router.navigate(['/questions']);
    });
  }
}
```

Create `ui/src/app/auth/login/login.component.html`:

```html
<div class="login-container">
  <div class="login-card">
    <div class="login-logo">
      <span class="logo-icon">⬡</span>
