export class UserProfileComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private userService = inject(UserService);
  private questionService = inject(QuestionService);

  protected user = signal<User | null>(null);
  protected questions = signal<Question[]>([]);
  protected isLoading = signal(true);

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.userService.get(id).subscribe(user => {
      this.user.set(user);
      this.isLoading.set(false);
    });
    this.questionService.list({ sort: 'newest' }).subscribe(res => {
      // Filter questions by this user — ideally the API supports userId filter, but for now filter client-side
      this.questions.set(res.questions.filter(q => q.userId === id).slice(0, 10));
    });
  }
}
