```typescript
import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import {
  Question, QuestionListResponse, QuestionSort,
  CreateQuestionRequest, UpdateQuestionRequest
} from '../models/question.model';

@Injectable({ providedIn: 'root' })
export class QuestionService {
  private http = inject(HttpClient);
  private base = '/api/v1';

  list(params: { page?: number; sort?: QuestionSort; tag?: string; q?: string }): Observable<QuestionListResponse> {
    let p = new HttpParams();
    if (params.page) p = p.set('page', params.page);
    if (params.sort) p = p.set('sort', params.sort);
    if (params.tag) p = p.set('tag', params.tag);
    if (params.q) p = p.set('q', params.q);
    return this.http.get<QuestionListResponse>(`${this.base}/questions`, { params: p });
  }

  get(id: number): Observable<Question> {
    return this.http.get<Question>(`${this.base}/questions/${id}`);
  }

  create(req: CreateQuestionRequest): Observable<Question> {
    return this.http.post<Question>(`${this.base}/questions`, req);
  }

  update(id: number, req: UpdateQuestionRequest): Observable<Question> {
    return this.http.put<Question>(`${this.base}/questions/${id}`, req);
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(`${this.base}/questions/${id}`);
  }

  vote(id: number, voteType: 1 | -1 | 0): Observable<Question> {
    return this.http.post<Question>(`${this.base}/questions/${id}/vote`, { voteType });
  }
}
```

