```typescript
import { Component, OnInit, inject, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, ActivatedRoute, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { QuestionService } from '../../../services/question.service';
import { Question, QuestionSort } from '../../../models/question.model';

@Component({
  selector: 'app-question-list',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './question-list.component.html',
  styleUrl: './question-list.component.scss'
})
export class QuestionListComponent implements OnInit {
  private service = inject(QuestionService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);

  protected questions = signal<Question[]>([]);
  protected total = signal(0);
  protected page = signal(1);
  protected pageSize = 15;
  protected sort = signal<QuestionSort>('newest');
  protected tagFilter = signal('');
  protected isLoading = signal(true);
  protected error = signal('');

  protected totalPages = computed(() => Math.ceil(this.total() / this.pageSize));

  protected sortOptions: { label: string; value: QuestionSort }[] = [
    { label: 'Newest', value: 'newest' },
    { label: 'Active', value: 'active' },
    { label: 'Votes', value: 'votes' },
    { label: 'Unanswered', value: 'unanswered' },
  ];

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      this.page.set(Number(params['page']) || 1);
      this.sort.set(params['sort'] || 'newest');
      this.tagFilter.set(params['tag'] || '');
      this.load();
    });
  }

  protected load(): void {
    this.isLoading.set(true);
    this.service.list({
      page: this.page(),
      sort: this.sort(),
      tag: this.tagFilter() || undefined,
    }).subscribe({
      next: res => {
        this.questions.set(res.questions);
        this.total.set(res.total);
        this.isLoading.set(false);
      },
      error: () => {
        this.error.set('Failed to load questions.');
        this.isLoading.set(false);
      }
    });
  }

  protected setSort(s: QuestionSort): void {
    this.router.navigate([], { queryParams: { sort: s, page: 1 }, queryParamsHandling: 'merge' });
  }

  protected setPage(p: number): void {
    this.router.navigate([], { queryParams: { page: p }, queryParamsHandling: 'merge' });
  }

  protected pages(): number[] {
    const tp = this.totalPages();
    const cur = this.page();
    const range: number[] = [];
    const start = Math.max(1, cur - 2);
    const end = Math.min(tp, cur + 2);
    for (let i = start; i <= end; i++) range.push(i);
    return range;
  }
}
```

