import { Component, OnInit, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { QuestionService } from '../../../services/question.service';
import { AnswerService } from '../../../services/answer.service';
import { AuthService } from '../../../auth/auth.service';
import { Question } from '../../../models/question.model';
import { Answer } from '../../../models/answer.model';

@Component({
  selector: 'app-question-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './question-detail.component.html',
  styleUrl: './question-detail.component.scss'
})
export class QuestionDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private questionService = inject(QuestionService);
  private answerService = inject(AnswerService);
  protected auth = inject(AuthService);
  private sanitizer = inject(DomSanitizer);

  protected question = signal<Question | null>(null);
  protected isLoading = signal(true);
  protected error = signal('');
  protected newAnswerBody = '';
  protected isSubmitting = signal(false);
  protected commentBody: Record<string, string> = {};
  protected showCommentForm: Record<string, boolean> = {};

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.questionService.get(id).subscribe({
      next: q => {
        this.question.set(q);
        this.isLoading.set(false);
      },
      error: () => {
        this.error.set('Question not found.');
        this.isLoading.set(false);
      }
    });
  }

  protected safeHtml(html: string): SafeHtml {
    return this.sanitizer.bypassSecurityTrustHtml(html);
  }

  protected voteQuestion(voteType: 1 | -1): void {
    const q = this.question();
    if (!q) return;
    const next = q.myVote === voteType ? 0 : voteType;
    this.questionService.vote(q.id, next as 1 | -1 | 0).subscribe(updated => {
      this.question.set({ ...q, score: updated.score, myVote: updated.myVote });
    });
  }

  protected voteAnswer(answer: Answer, voteType: 1 | -1): void {
    const q = this.question();
    if (!q) return;
    const next = answer.myVote === voteType ? 0 : voteType;
    this.answerService.vote(answer.id, next as 1 | -1 | 0).subscribe(updated => {
      const answers = q.answers?.map(a => a.id === answer.id ? updated : a) ?? [];
      this.question.set({ ...q, answers });
    });
  }

  protected acceptAnswer(answer: Answer): void {
    const q = this.question();
    if (!q) return;
    this.answerService.accept(answer.id).subscribe(() => {
      const answers = q.answers?.map(a => ({ ...a, isAccepted: a.id === answer.id })) ?? [];
      this.question.set({ ...q, acceptedAnswerId: answer.id, isAnswered: true, answers });
    });
  }

  protected submitAnswer(): void {
    if (!this.newAnswerBody.trim()) return;
    const q = this.question();
    if (!q) return;
    this.isSubmitting.set(true);
    this.answerService.create(q.id, { bodyMarkdown: this.newAnswerBody }).subscribe({
      next: answer => {
        this.question.set({ ...q, answers: [...(q.answers ?? []), answer] });
        this.newAnswerBody = '';
        this.isSubmitting.set(false);
      },
      error: () => this.isSubmitting.set(false)
    });
  }

  protected isQuestionAuthor(): boolean {
    const q = this.question();
    const user = this.auth.currentUser();
    return !!q && !!user && q.userId === user.id;
  }

  protected isAnswerAuthor(answer: Answer): boolean {
    const user = this.auth.currentUser();
    return !!user && answer.userId === user.id;
  }
}
