```typescript
import { Component, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { QuestionService } from '../../../services/question.service';
import { TagService } from '../../../services/tag.service';
import { Tag } from '../../../models/tag.model';
import { debounceTime, distinctUntilChanged, Subject, switchMap } from 'rxjs';

@Component({
  selector: 'app-ask-question',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './ask-question.component.html',
  styleUrl: './ask-question.component.scss'
})
export class AskQuestionComponent {
  private service = inject(QuestionService);
  private tagService = inject(TagService);
  private router = inject(Router);

  protected title = '';
  protected body = '';
  protected tagInput = '';
  protected selectedTags = signal<Tag[]>([]);
  protected tagSuggestions = signal<Tag[]>([]);
  protected isSubmitting = signal(false);
  protected errors = signal<Record<string, string>>({});

  private tagSearch$ = new Subject<string>();

  constructor() {
    this.tagSearch$.pipe(
      debounceTime(200),
      distinctUntilChanged(),
      switchMap(q => this.tagService.list(q || undefined))
    ).subscribe(res => this.tagSuggestions.set(res.tags.slice(0, 8)));
  }

  protected onTagInputChange(): void {
    this.tagSearch$.next(this.tagInput);
  }

  protected selectTag(tag: Tag): void {
    const current = this.selectedTags();
    if (!current.find(t => t.id === tag.id) && current.length < 5) {
      this.selectedTags.set([...current, tag]);
    }
    this.tagInput = '';
    this.tagSuggestions.set([]);
  }

  protected removeTag(tag: Tag): void {
    this.selectedTags.set(this.selectedTags().filter(t => t.id !== tag.id));
  }

  protected submit(): void {
    const errs: Record<string, string> = {};
    if (!this.title.trim()) errs['title'] = 'Title is required.';
    if (this.title.length < 10) errs['title'] = 'Title must be at least 10 characters.';
    if (!this.body.trim()) errs['body'] = 'Question body is required.';
    if (this.selectedTags().length === 0) errs['tags'] = 'At least one tag is required.';
    this.errors.set(errs);
    if (Object.keys(errs).length > 0) return;

    this.isSubmitting.set(true);
    this.service.create({
      title: this.title.trim(),
      bodyMarkdown: this.body.trim(),
      tagNames: this.selectedTags().map(t => t.name),
    }).subscribe({
      next: q => this.router.navigate(['/questions', q.id]),
      error: () => {
        this.errors.set({ submit: 'Failed to post question. Please try again.' });
        this.isSubmitting.set(false);
      }
    });
  }
}
