import { Component, OnInit, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { TagService } from '../../../services/tag.service';
import { QuestionService } from '../../../services/question.service';
import { Tag } from '../../../models/tag.model';
import { Question } from '../../../models/question.model';

@Component({
  selector: 'app-tag-detail',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './tag-detail.component.html',
  styleUrl: './tag-detail.component.scss'
})
export class TagDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private tagService = inject(TagService);
  private questionService = inject(QuestionService);

  protected tag = signal<Tag | null>(null);
  protected questions = signal<Question[]>([]);
  protected isLoading = signal(true);

  ngOnInit(): void {
    const name = this.route.snapshot.paramMap.get('name')!;
    this.tagService.getByName(name).subscribe(tag => {
      this.tag.set(tag);
    });
    this.questionService.list({ tag: name, sort: 'newest' }).subscribe(res => {
      this.questions.set(res.questions);
      this.isLoading.set(false);
    });
  }
}
