export class SearchResultsComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private service = inject(SearchService);

  protected results = signal<SearchResult[]>([]);
  protected query = signal('');
  protected isLoading = signal(false);

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      const q = params['q'] || '';
      this.query.set(q);
      if (q) {
        this.isLoading.set(true);
        this.service.search(q).subscribe(res => {
          this.results.set(res.results);
          this.isLoading.set(false);
        });
      }
    });
  }

  protected routerLinkFor(r: SearchResult): string[] {
    return r.type === 'question' ? ['/questions', String(r.id)] : ['/articles', String(r.id)];
  }
}
```

