Create `scripts/bootstrap.sh`:

```bash
#!/usr/bin/env bash
set -euo pipefail

POSTGRES_CONTAINER="heapoverflow-postgres"
POSTGRES_PORT="${POSTGRES_PORT:-5432}"
POSTGRES_USER="${POSTGRES_USER:-heapoverflow}"
POSTGRES_PASSWORD="${POSTGRES_PASSWORD:-heapoverflow}"
POSTGRES_DB="${POSTGRES_DB:-heapoverflow}"
DATABASE_URL="postgres://${POSTGRES_USER}:${POSTGRES_PASSWORD}@localhost:${POSTGRES_PORT}/${POSTGRES_DB}?sslmode=disable"

# Start postgres if not running
if ! docker ps --format '{{.Names}}' | grep -q "^${POSTGRES_CONTAINER}$"; then
  echo "Starting PostgreSQL container..."
  docker run -d \
    --name "${POSTGRES_CONTAINER}" \
    -e POSTGRES_USER="${POSTGRES_USER}" \
    -e POSTGRES_PASSWORD="${POSTGRES_PASSWORD}" \
    -e POSTGRES_DB="${POSTGRES_DB}" \
    -p "${POSTGRES_PORT}:5432" \
    postgres:16-alpine
  echo "Waiting for PostgreSQL to be ready..."
  until docker exec "${POSTGRES_CONTAINER}" pg_isready -U "${POSTGRES_USER}" -d "${POSTGRES_DB}" >/dev/null 2>&1; do
    sleep 1
  done
  echo "PostgreSQL ready."
fi

export DATABASE_URL

# Run migrations (via Go binary)
echo "Running migrations..."
go run ./cmd/server -migrate-only

# Import data if not already imported
echo "Importing data..."
go run ./cmd/importer

echo "Bootstrap complete. DATABASE_URL=${DATABASE_URL}"
```

